import{_ as d,C as a,c as t,o as c,aa as s,G as l}from"./chunks/framework.Cn7WEiMX.js";const b=JSON.parse('{"title":"eCloud 连接被阻止","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"PlaceholderAPI","link":"/wiki/PlaceholderAPI"},{"title":"common-issues","link":"/wiki/PlaceholderAPI/common-issues"},{"title":"eCloud 连接被阻止","link":"/wiki/PlaceholderAPI/common-issues/ecloud-connection-blocked"}]},"headers":[],"relativePath":"wiki/PlaceholderAPI/common-issues/ecloud-connection-blocked.md","filePath":"wiki/PlaceholderAPI/common-issues/ecloud-connection-blocked.md"}'),r={name:"wiki/PlaceholderAPI/common-issues/ecloud-connection-blocked.md"};function n(h,e,p,u,k,P){const o=a("NolebaseGitContributors"),i=a("NolebaseGitChangelog");return c(),t("div",null,[e[0]||(e[0]=s(`<h1 id="ecloud-连接被阻止" tabindex="-1">eCloud 连接被阻止 <a class="header-anchor" href="#ecloud-连接被阻止" aria-label="Permalink to &quot;eCloud 连接被阻止&quot;">​</a></h1> <p>如果你不能通过 PlaceholderAPI 自带的命令下载变量拓展，有可能是因为你的服务器无法连接到 PlaceholderAPI 变量拓展云（即 eCloud）。这一般是服务器提供商限制了对外网的访问，或是防火墙问题。</p> <h2 id="症状" tabindex="-1">症状 <a class="header-anchor" href="#症状" aria-label="Permalink to &quot;症状&quot;">​</a></h2> <p>一般表现为：</p> <ul><li>游戏内消息将你重定向到这个页面。</li> <li><code>/papi ecloud download/update &lt;变量拓展名称&gt;</code> 失败（超时、错误、连接被拒绝等字样）</li></ul> <h2 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h2> <p>下载命令需要从服务器出站访问 PlaceholderAPI 的 eCloud API。</p> <p>连接有可能被这些东西阻止：</p> <ul><li>托管商设置的防火墙/安全策略</li> <li>本地防火墙</li> <li>网络防火墙（数据中心、路由等）</li> <li>DNS 过滤或上游的服务器提供商拦截规则</li></ul> <h2 id="placeholderapi-使用的域名" tabindex="-1">PlaceholderAPI 使用的域名 <a class="header-anchor" href="#placeholderapi-使用的域名" aria-label="Permalink to &quot;PlaceholderAPI 使用的域名&quot;">​</a></h2> <p>请放行如下域名的 HTTPS（TCP 443）出站流量：</p> <ul><li>低于 2.12.0 版本的 PlaceholderAPI：<code>api.extendedclip.com</code></li> <li>高于 2.12.0 版本的 PlaceholderAPI：<code>*.placeholderapi.com</code></li></ul> <h2 id="修复指南" tabindex="-1">修复指南 <a class="header-anchor" href="#修复指南" aria-label="Permalink to &quot;修复指南&quot;">​</a></h2> <h3 id="_1-请求托管商解封-ecloud-域名" tabindex="-1">1）请求托管商解封 eCloud 域名 <a class="header-anchor" href="#_1-请求托管商解封-ecloud-域名" aria-label="Permalink to &quot;1）请求托管商解封 eCloud 域名&quot;">​</a></h3> <p>如果你正在使用托管商的服务器，你可能无法自行修改防火墙规则。</p> <p>联系客服并请求解封上述域名的 HTTPS 出站流量。</p> <h3 id="_2-检查防火墙-过滤设置" tabindex="-1">2）检查防火墙/过滤设置 <a class="header-anchor" href="#_2-检查防火墙-过滤设置" aria-label="Permalink to &quot;2）检查防火墙/过滤设置&quot;">​</a></h3> <p>如果你是自建服务器，你可以检查这些设置：</p> <ul><li>系统防火墙规则（Windows 防火墙 / <code>ufw</code> / <code>iptables</code>）</li> <li>路由/数据中心防火墙规则</li> <li>DNS 过滤</li></ul> <h3 id="_3-手动安装拓展-无需连接-ecloud" tabindex="-1">3）手动安装拓展（无需连接 eCloud） <a class="header-anchor" href="#_3-手动安装拓展-无需连接-ecloud" aria-label="Permalink to &quot;3）手动安装拓展（无需连接 eCloud）&quot;">​</a></h3> <p>如果无法解除封锁，你可以这样手动下载拓展：</p> <ul><li>前往 <a href="https://ecloud.placeholderapi.com/" target="_blank" rel="noreferrer">https://ecloud.placeholderapi.com/</a></li> <li>搜索并打开你想要的变量拓展。</li> <li>下载 <code>.jar</code> 文件。</li> <li>将其放入服务器的 <code>plugins/PlaceholderAPI/expansions/</code> 文件夹。</li> <li>输入命令 <a href="./../user-guides/commands#papi-reload"><code>/papi reload</code></a>（或重启服务器）。</li></ul> <h2 id="快速连通性检查-可选" tabindex="-1">快速连通性检查（可选） <a class="header-anchor" href="#快速连通性检查-可选" aria-label="Permalink to &quot;快速连通性检查（可选）&quot;">​</a></h2> <p>如果你能接触到运行服务器的实体机，通过终端或命令窗口进行这些检查可以确认连接是否被阻止。</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ecloud.placeholderapi.com/api/v3/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.extendedclip.com/v2/</span></span></code></pre></div><p>如果这些命令在服务器端失败，而在你的电脑或网络上有效，那么服务器托管商或数据中心网络极有可能阻止了这类域名的出站连接。</p> <h2 id="还是有问题" tabindex="-1">还是有问题？ <a class="header-anchor" href="#还是有问题" aria-label="Permalink to &quot;还是有问题？&quot;">​</a></h2> <p>如果你需要帮助，你可以加入 <a href="https://discord.gg/helpchat" target="_blank" rel="noreferrer">Discord 聊天群组</a>，分享这些信息：</p> <ul><li>你试过的修复方法</li> <li>下载尝试的完整控制台报错</li> <li><code>/papi dump</code> 命令输出的链接</li></ul> `,57)),l(o),l(i)])}const _=d(r,[["render",n]]);export{b as __pageData,_ as default};
